using System;
using TaleWorlds.Library;

namespace AnimusForge;

// On-click read-only help. No discovery, IO, downloads or synthesis on provider changes.
internal static class GptSoVitsLiteGuide
{
    internal const int ChapterCount = 8;
    internal static string Title(int chapter)
    {
        switch (chapter)
        {
            case 0: return GptSoVitsUiText.Text("LiteGuideDownload", "L guide 1 - Download and version");
            case 1: return GptSoVitsUiText.Text("LiteGuideInstall", "L guide 2 - Installation");
            case 2: return GptSoVitsUiText.Text("LiteGuideUse", "L guide 3 - Enable and assign voices");
            case 3: return GptSoVitsUiText.Text("LiteGuideHardware", "L guide 4 - VRAM and performance");
            case 4: return GptSoVitsUiText.Text("LiteGuideRecordings", "L guide 5 - Custom recordings");
            case 5: return GptSoVitsUiText.Text("LiteGuideManifest", "L guide 6 - Folders and manifest");
            case 6: return GptSoVitsUiText.Text("LiteGuideLanguage", "L guide 7 - Language and emotion");
            case 7: return GptSoVitsUiText.Text("LiteGuideTroubleshoot", "L guide 8 - Troubleshooting and updates");
            default: throw new ArgumentOutOfRangeException(nameof(chapter));
        }
    }
    internal static string Body(int chapter)
    {
        switch (chapter)
        {
            case 0: return GptSoVitsUiText.Text("LiteGuideDownloadBody", "Download: AF-GPTSOVITS-L_0.1.0.zip\nBaidu Netdisk: https://pan.baidu.com/s/1Wsl1hXm5Mz2_7DRetX94FA?pwd=5qkj\nExtraction code: 5qkj\nThis is an optional lightweight voice add-on for AF, not the main AF mod or the upstream training distribution. An AF build with AF-GPTSOVITS support is required.\nThe local same-version test archive is about 5GB compressed / 7.3GiB extracted. Allow about 15GB for download, extraction and cache; check the actual shared file size. A future U edition needs its own download and guide; L memory figures do not apply to U.");
            case 1: return GptSoVitsUiText.Text("LiteGuideInstallBody", "1. Close the game and launcher; extract to a temporary folder first.\n2. Put AF-GPTSOVITS-L and VoicePacks inside the existing Modules/AnimusForge folder. If the archive has an AnimusForge wrapper, merge its contents rather than nesting AnimusForge twice.\n3. Check Modules/AnimusForge/AF-GPTSOVITS-L/runtime.json and Modules/AnimusForge/VoicePacks. Keep server.py, lite_engine.py, app and runtime intact.\n4. The add-on must not replace AF bin, SubModule.xml, ModuleData or gameplay files. Preserve custom voices and existing manifests; never delete the whole AF module.\n5. No separate Python installation or old port-9880 server is needed; AF owns its managed process.");
            case 2: return GptSoVitsUiText.Text("LiteGuideUseBody", "In MCM TTS API / speech settings, select AF-GPTSOVITS-L / U (auto) and enable speech. AF detects a compatible package and prefers L when both are present. Wait for Ready, then test local speech. Cold starts can take tens of seconds to a minute or two; do not repeatedly refresh.\nChoose a voice in the character encyclopedia even before the first conversation. Named characters retain their random selection. Male/Female are same-gender default pools; Custom is manual-only.\nLocal L/U speech reads only the primary interlocutor; bystanders keep text. Private dialogue uses its current target. Peaceful meetings are allowed; real combat blocks local synthesis. Accepted complete replies are read sentence by sentence, not unchecked token-by-token.\nAfter adding voices, refresh local runtime status or restart. Disabling speech releases only the service AF started.");
            case 3: return GptSoVitsUiText.Text("LiteGuideHardwareBody", "A compatible NVIDIA GPU with 8GB VRAM is a practical starting point for testing; 12GB/16GB leaves more room beside the game. This is not a guarantee or a reason to buy a GPU solely for this add-on. Cards with 6GB or less are not recommended for concurrent gaming; consider a manually selected remote TTS service. This portable build targets Windows/CUDA; AMD, Intel and CPU-only plug-and-play operation is not validated.\nL targets roughly 2GiB VRAM, NOT a hard cap. On a 16GB RTX 5070 Ti, 17 real syntheses sampled every 100ms peaked around 1546MiB (1.51GiB) of process dedicated VRAM. This is not an 8GB-card/game coexistence test and may miss short spikes.\nOn 8GB cards, leave roughly 2–3GB headroom for speech, lower game texture/graphics settings and close other GPU apps. An audition is not a long-session stability test. Watch total dedicated VRAM, stalls and long lines; disable local speech or select remote TTS if needed. VRAM, system RAM and disk space are separate budgets.");
            case 4: return GptSoVitsUiText.Text("LiteGuideRecordingsBody", "A reference voice pack is not a trained model: it uses recordings, exact transcripts and manifest.json. Arbitrary .pth/.ckpt files are not plug-and-play character packs.\nRecommended: one speaker, clean mono PCM16 WAV, about 3–10 seconds per reference; 16kHz is a suitable input. Do not upsample merely to claim quality. Avoid music, other voices, clipping, reverb or silence-only clips. Each file must be nonempty and no larger than 8MiB.\nprompt_text must match that exact recording (1–1000 characters); prompt_lang describes the reference audio, not the requested speech language. This L build recommends zh/en/ja/yue.\nUse the same character for every emotional reference. Recalculate SHA-256 after editing WAV files and update the manifest. Use voices you have permission to use; public distribution also needs rights to the recordings/character assets. An open-source code license does not license voice recordings.");
            case 5: return GptSoVitsUiText.Text("LiteGuideManifestBody", "Example: VoicePacks/Custom/MyVoice-AF-C100/manifest.json, with reference.wav beside it and tones/angry.wav below it. Discovery scans one package-folder level under Male/Female/Custom; do not add another download-wrapper folder. category is male/female/custom respectively; default-pool category must match gender.\nEach profiles entry needs a stable unique id (1–128 characters, no outer spaces), label, speaker_metadata.gender (male/female), category, reference_file, reference_sha256 (the real 64-digit SHA-256), prompt_lang and prompt_text. Prefer English labels plus a permanent style_target code, e.g. My Voice · AF-C100. Paths are relative to the pack and cannot escape it or use absolute drive paths.\nOptional emotion_variants keys are neutral/happy/angry/sad; each has its own path, hash, language and exact transcript. Limits: 2MiB per manifest, 128 manifests / 8MiB metadata / 512 voices overall. See docs/tts/manifest.example.json on GitHub; replace its placeholder hashes before use.");
            case 6: return GptSoVitsUiText.Text("LiteGuideLanguageBody", "Speech output language accepts Chinese, Cantonese, English or Japanese, including their Chinese names. Blank/auto follows the reply. All four providers share it: matching text is kept; otherwise postprocessing privately translates speech without changing subtitles or history. Typing the Chinese word for Japanese selects a language code, not spoken content. Failed or missing translation stays text-only.\nLocal tone uses the existing postprocessed MOOD, not gameplay action tags: JOY/DELIGHTED maps to happy, ANNOYED to angry, otherwise neutral; sad is available for manual audition.\nKeep one stable ID per character and put emotional references in emotion_variants; do not split Sparkle into four characters. Missing tones use the base reference. An angry reference helps but does not guarantee acting quality. Invented cute/flirty categories are not supported by the current automatic tag mapping.");
            case 7: return GptSoVitsUiText.Text("LiteGuideTroubleshootBody", "No audio: check speech enabled, selected provider, runtime ready state, primary target, encyclopedia voice, combat restrictions and valid postprocessed translation when a language is forced. Bad reference paths/hashes, duplicate IDs or missing model files are rejected; AF does not silently switch to a paid API.\nRefresh or restart after adding packs. Re-extract an incomplete package; never replace it while running. If language selection reports an old runtime, update the matching L package instead of editing runtime.json to bypass verification.\nErrors: Logs/TTS; temporary cache: Cache/TTS. Report the error, AF/package version, GPU and reproduction steps after redacting API keys, tokens and private dialogue.\nMerge only the intended add-on; retain custom voices, character IDs, settings and other mods. Use trusted executable packages. The supplied share link does not establish redistribution rights for every recording. U requires a separate hardware and compatibility guide when released.");
            default: throw new ArgumentOutOfRangeException(nameof(chapter));
        }
    }
    internal static InquiryData CreatePage(int chapter)
        => new InquiryData(Title(chapter), Body(chapter), true, false,
            GptSoVitsUiText.Text("GuideClose", "Close"), null, null, null);
    internal static void OpenChapter(int chapter) => InformationManager.ShowInquiry(CreatePage(chapter), true);
}
